        core, prerelease = parse_version(v)
        # Create a key that sorts correctly
        # Core version is already numeric tuple
        # For prerelease, we need to convert to something sortable

        # Build a sortable prerelease key
        if prerelease is None:
            # Release version: use max values to sort after pre-release
            prerelease_key = (1,)  # Sort after pre-releases
